/* =====================================================================
   DL — step-by-step notes for syllabus.html
   One syllabus topic = one small predicted question (an array when a topic
   needs a theory step and a numerical step). Key = module.entry.topic.
   Note: {q, m (marks), a (plain text for SEM7.ui.rich, or HTML), trap, ask[]}
   Follows the class decks in _resources/dl (as built into the DL site) and
   standard deep-learning references. The small worked examples are made for
   these notes.
   ===================================================================== */
(function(){
  "use strict";
  var N = (window.SEM7_NOTES = window.SEM7_NOTES || {}).dl = {};

  /* ------------------------------------------------ Module 1 */
  N["0.0.0"] = { q:"Explain the biological neuron. Compare it with an artificial neuron.", m:5,
      a:"<p><b>Biological neuron</b> parts:</p><ul><li><b>Dendrites:</b> receive signals from other neurons.</li><li><b>Cell body (soma):</b> sums the incoming signals.</li><li><b>Axon:</b> carries the output signal away.</li><li><b>Synapse:</b> the junction to the next neuron; its strength decides how much signal passes.</li></ul><p>The neuron fires when the summed input crosses a threshold.</p><table><tr><th>Biological</th><th>Artificial</th></tr><tr><td>Dendrites</td><td>Inputs x</td></tr><tr><td>Synapse strength</td><td>Weights w</td></tr><tr><td>Soma</td><td>Summation Σ w x + b</td></tr><tr><td>Firing threshold</td><td>Activation function</td></tr><tr><td>Axon</td><td>Output y</td></tr></table>",
      ask:["Draw and label a biological neuron"] };
  N["0.1.0"] = { q:"Explain the McCulloch-Pitts neuron. Implement AND and OR.", m:5,
      a:"McCulloch-Pitts neuron (1943) — the first mathematical model of a neuron.\n- Inputs and output are binary (0 or 1).\n- Inputs are excitatory or inhibitory; all excitatory weights are equal (1).\n- Output y = 1 if the sum of the inputs ≥ threshold θ, else 0.\n- If any inhibitory input is 1, the output is 0.\n- No learning: the threshold is fixed by hand.\nAND (two inputs): θ = 2. Only 1 + 1 = 2 fires.\nOR (two inputs): θ = 1. Any input 1 fires.\nNOT: one inhibitory input, θ = 0.\nLimitations: binary only; no weights to learn; cannot do XOR with one neuron.",
      trap:"The MP neuron has no learning rule. Thresholds are chosen by analysis.",
      ask:["Implement NOR / NAND / AND-NOT with an MP neuron"] };
  N["0.1.1"] = { q:"What is a perceptron? How does it differ from the MP neuron?", m:5,
      a:"<p><b>Perceptron</b> (Rosenblatt, 1958): a single neuron with real-valued inputs and learnable weights.</p><p>net = Σ w<sub>i</sub> x<sub>i</sub> + b; output y = 1 if net ≥ 0, else 0 (step function).</p><p>It draws a straight line (hyperplane) w·x + b = 0 that separates two classes.</p><table><tr><th></th><th>MP neuron</th><th>Perceptron</th></tr><tr><td>Inputs</td><td>Binary</td><td>Real numbers</td></tr><tr><td>Weights</td><td>Fixed, equal</td><td>Real, different, learned</td></tr><tr><td>Threshold</td><td>Set by hand</td><td>Learned (as the bias)</td></tr><tr><td>Learning</td><td>None</td><td>Perceptron learning rule</td></tr></table>",
      ask:["Draw the perceptron model"] };
  N["0.1.2"] = { q:"What is a Multilayer Perceptron (MLP)?", m:5,
      a:"MLP — a feedforward network with an input layer, one or more hidden layers and an output layer; every neuron is connected to all the neurons of the next layer.\n- Hidden neurons use non-linear activation functions (sigmoid, tanh, ReLU).\n- Information flows forward only.\n- Trained by backpropagation.\nWhy: a single perceptron can separate only linearly separable classes. Hidden layers combine several lines into curved decision boundaries.\nXOR needs one hidden layer with 2 neurons.\nUniversal approximation theorem: an MLP with one hidden layer and enough neurons can approximate any continuous function.",
      ask:["Solve XOR with a multilayer perceptron", "Perceptron vs MLP"] };
  N["0.2.0"] = { q:"State the perceptron learning rule. Update w = (0, 0), b = 0 for x = (1, 1), target 1, η = 1.", m:5,
      a:"Rule: w(new) = w(old) + η (t − y) x; b(new) = b(old) + η (t − y)\n- t: target; y: actual output; η: learning rate.\n- If the output is correct, (t − y) = 0 and nothing changes.\nAlgorithm:\n1. Initialise the weights and bias.\n2. For each training example compute y.\n3. Update if y ≠ t.\n4. Repeat until there is no error in a full pass (epoch).\nNumerical (y = 1 if net > 0):\n1. net = 0×1 + 0×1 + 0 = 0 → y = 0\n2. Error = t − y = 1\n3. w = (0, 0) + 1 × 1 × (1, 1) = (1, 1)\n4. b = 0 + 1 = 1\nPerceptron convergence theorem: if the classes are linearly separable, the rule converges in a finite number of steps.",
      ask:["Train a perceptron for the AND gate; show one epoch"] };
  N["0.2.1"] = { q:"State the delta learning rule. How does it differ from the perceptron rule?", m:5,
      a:"<p><b>Delta rule (Widrow-Hoff, LMS):</b> change the weights to reduce the squared error E = ½ (t − y)², by gradient descent.</p><p>Δw = η (t − y) f′(net) x. For a linear neuron f′ = 1, so Δw = η (t − y) x.</p><p><b>Numerical</b> (linear): w = 0.2, x = 2, t = 1, η = 0.1.</p><ol><li>y = 0.2 × 2 = 0.4</li><li>Error = 1 − 0.4 = 0.6</li><li>Δw = 0.1 × 0.6 × 2 = 0.12</li><li>w = 0.32</li></ol><table><tr><th></th><th>Perceptron rule</th><th>Delta rule</th></tr><tr><td>Activation</td><td>Step</td><td>Continuous, differentiable</td></tr><tr><td>Error used</td><td>After thresholding (0 or ±1)</td><td>Before thresholding (real value)</td></tr><tr><td>Basis</td><td>Error correction</td><td>Gradient descent on squared error</td></tr><tr><td>Non-separable data</td><td>Never converges</td><td>Converges to the least-squares fit</td></tr></table><p>Backpropagation is the delta rule generalised to many layers.</p>",
      ask:["Perceptron learning vs delta learning"] };
  N["0.3.0"] = { q:"What are linearly separable classes?", m:3,
      a:"Linearly separable — two classes that can be separated completely by a straight line (in 2D), a plane (3D) or a hyperplane.\nw1 x1 + w2 x2 + b = 0 is the decision boundary.\nExamples: AND, OR, NAND, NOR.\nAND: (0,0), (0,1), (1,0) → 0 and (1,1) → 1. The line x1 + x2 = 1.5 separates them.\nA single perceptron can learn any linearly separable function.",
      ask:["Show that the OR function is linearly separable"] };
  N["0.3.1"] = { q:"What are linearly non-separable classes? Explain the XOR problem.", m:5,
      a:"<p><b>Linearly non-separable:</b> no single straight line can separate the classes.</p><table><tr><th>x1</th><th>x2</th><th>XOR</th></tr><tr><td>0</td><td>0</td><td>0</td></tr><tr><td>0</td><td>1</td><td>1</td></tr><tr><td>1</td><td>0</td><td>1</td></tr><tr><td>1</td><td>1</td><td>0</td></tr></table><p>The 1s lie on one diagonal and the 0s on the other: no line puts (0,1), (1,0) on one side and (0,0), (1,1) on the other.</p><p><b>Proof idea:</b> we would need b &lt; 0, w2 + b ≥ 0, w1 + b ≥ 0 and w1 + w2 + b &lt; 0. Adding the middle two gives w1 + w2 + 2b ≥ 0, which contradicts the others.</p><p><b>Solution:</b> a hidden layer. XOR = (x1 OR x2) AND NOT (x1 AND x2): two hidden neurons + one output neuron.</p><p>Minsky and Papert (1969) showed this limit of the single perceptron.</p>",
      ask:["Why can a single perceptron not solve XOR?"] };
  N["0.4.0"] = { q:"What is deep learning? How does it differ from machine learning?", m:5,
      a:"<p><b>Deep learning:</b> a part of machine learning that uses neural networks with many hidden layers to learn features from data automatically, layer by layer (edges → shapes → objects).</p><table><tr><th></th><th>Machine learning</th><th>Deep learning</th></tr><tr><td>Features</td><td>Hand-crafted by experts</td><td>Learned automatically</td></tr><tr><td>Data needed</td><td>Small to medium</td><td>Very large</td></tr><tr><td>Hardware</td><td>CPU</td><td>GPU</td></tr><tr><td>Training time</td><td>Short</td><td>Long</td></tr><tr><td>Interpretability</td><td>Higher</td><td>Lower (black box)</td></tr><tr><td>Best for</td><td>Tabular data</td><td>Images, speech, text</td></tr></table><p>AI ⊃ Machine learning ⊃ Deep learning.</p>",
      ask:["Why did deep learning become successful recently?"] };
  N["0.4.1"] = { q:"Give a brief history of deep learning.", m:5,
      a:"- 1943: McCulloch and Pitts: the first mathematical neuron.\n- 1958: Rosenblatt: the perceptron and its learning rule.\n- 1969: Minsky and Papert show that a perceptron cannot learn XOR; interest falls (AI winter).\n- 1986: Rumelhart, Hinton and Williams: backpropagation makes multilayer networks trainable.\n- 1997: LSTM (Hochreiter and Schmidhuber).\n- 1998: LeCun: LeNet-5 for handwritten digits.\n- 2006: Hinton: deep belief networks; the term 'deep learning'.\n- 2012: AlexNet wins ImageNet with ReLU, dropout and GPUs.\n- 2014: GANs.\n- 2017: Transformers.",
      ask:["Milestones in the development of neural networks"] };
  N["0.5.0"] = { q:"Define the basic terminologies of deep learning.", m:5,
      a:"- Neuron (unit): computes a weighted sum and applies an activation.\n- Weights and bias: the learnable parameters.\n- Layer: input, hidden, output.\n- Activation function: adds non-linearity (sigmoid, tanh, ReLU).\n- Forward propagation: input → output.\n- Loss function: measures the error between prediction and target.\n- Backpropagation: computes the gradients of the loss with respect to the weights.\n- Optimizer: updates the weights (gradient descent, Adam).\n- Learning rate: the step size of an update.\n- Epoch: one pass over the whole training set.\n- Batch: the examples used for one update. Iteration: one update.\n- Hyperparameters: set before training (learning rate, number of layers, batch size).\n- Overfitting: good on training data, poor on new data.",
      trap:"Parameters are learned (weights). Hyperparameters are chosen (learning rate).",
      ask:["Epoch vs batch vs iteration", "Parameter vs hyperparameter"] };
  N["0.6.0"] = { q:"What are the classes of deep learning models?", m:5,
      a:"<table><tr><th>Class</th><th>Learns from</th><th>Models</th><th>Use</th></tr><tr><td>Supervised (discriminative)</td><td>Labelled data</td><td>MLP, CNN, RNN / LSTM</td><td>Classification, regression</td></tr><tr><td>Unsupervised (generative)</td><td>Unlabelled data</td><td>Autoencoders, RBM, GAN, diffusion</td><td>Feature learning, generation</td></tr><tr><td>Hybrid</td><td>Both</td><td>Pre-train unsupervised, then fine-tune supervised</td><td>Small labelled data</td></tr><tr><td>Reinforcement</td><td>Rewards</td><td>Deep Q-network</td><td>Games, robotics</td></tr></table><p><b>By architecture:</b> feedforward (MLP), convolutional (CNN, images), recurrent (RNN, sequences), autoencoder, generative (GAN).</p>",
      ask:["Which deep learning architecture suits image / sequence data, and why?"] };

  /* ------------------------------------------------ Module 2 */
  N["1.0.0"] = { q:"Explain the multi-layered feedforward neural network.", m:5,
      a:"Structure: input layer → hidden layers → output layer; fully connected; no loops.\nForward pass for each layer:\n1. Pre-activation: a = W h(previous) + b\n2. Activation: h = g(a)\n3. Output layer: ŷ = O(a_L) (softmax or linear)\nNotation: n inputs, L − 1 hidden layers, weights W, biases b.\nTraining:\n1. Forward pass: compute ŷ.\n2. Compute the loss L(y, ŷ).\n3. Backward pass: compute the gradients by backpropagation.\n4. Update the weights by gradient descent.\n5. Repeat for many epochs.\nNumber of parameters between two layers = (inputs × outputs) + outputs.\nExample 3-4-2 network: (3×4 + 4) + (4×2 + 2) = 16 + 10 = 26.",
      ask:["Count the parameters of the given network", "Perform one forward pass for the given weights"] };
  N["1.0.1"] = { q:"What are the learning factors that affect the training of a network?", m:5,
      a:"<table><tr><th>Factor</th><th>Too low / few</th><th>Too high / many</th></tr><tr><td>Learning rate</td><td>Very slow convergence</td><td>Overshoots, may diverge</td></tr><tr><td>Hidden layers / neurons</td><td>Underfits</td><td>Overfits</td></tr><tr><td>Batch size</td><td>Noisy updates</td><td>Slow per epoch; may generalise worse</td></tr><tr><td>Epochs</td><td>Underfits</td><td>Overfits</td></tr><tr><td>Initial weights</td><td>All zero: symmetry is never broken</td><td>Too large: saturation, vanishing gradients</td></tr></table><p>Also: the choice of activation function (sigmoid saturates; ReLU can die), the momentum term, and the steepness of the activation.</p>",
      ask:["Why should weights not be initialised to zero?"] };
  N["1.1.0"] = { q:"Explain the tanh activation function.", m:3,
      a:"tanh(x) = (e^x − e^(−x)) ÷ (e^x + e^(−x))\n- Range: −1 to +1.\n- Zero-centred (unlike the sigmoid).\n- Derivative: 1 − tanh²(x); maximum 1 at x = 0.\n- S-shaped.\nAdvantage — zero-centred output makes training faster than with the sigmoid.\nDisadvantage — saturates for large |x|: the gradient becomes almost zero (vanishing gradient).\nUsed in: hidden layers of RNNs and LSTMs.",
      ask:["Sigmoid vs tanh"] };
  N["1.1.1"] = { q:"Explain the logistic (sigmoid) activation function.", m:3,
      a:"σ(x) = 1 ÷ (1 + e^(−x))\n- Range: 0 to 1; can be read as a probability.\n- σ(0) = 0.5.\n- Derivative: σ(x) (1 − σ(x)); maximum 0.25 at x = 0.\nAdvantage — smooth; good for the output of binary classification.\nDisadvantages:\n- Saturates: vanishing gradient.\n- Not zero-centred.\n- The exponential is costly to compute.\nUsed in: output layer for binary classification; gates of an LSTM.",
      trap:"The maximum derivative is 0.25. Multiplying many of these is what makes gradients vanish.",
      ask:["Derive the derivative of the sigmoid function"] };
  N["1.1.2"] = { q:"Explain the linear activation function.", m:2,
      a:"f(x) = x (or f(x) = c x)\n- Range: −∞ to +∞.\n- Derivative: constant.\nUsed in: the output layer for regression.\nWhy not in hidden layers: a stack of linear layers is still one linear function, W2 (W1 x) = (W2 W1) x. The network could not learn non-linear patterns, however deep it is.",
      ask:["Why are non-linear activation functions needed?"] };
  N["1.1.3"] = { q:"Explain the softmax function. Compute softmax for z = (2, 1, 0).", m:5,
      a:"softmax(zi) = e^(zi) ÷ Σ e^(zj)\n- Turns a vector of scores into probabilities.\n- Every output is between 0 and 1; they add up to 1.\n- Used in the output layer for multi-class classification.\nNumerical:\n1. e² = 7.389, e¹ = 2.718, e⁰ = 1\n2. Sum = 11.107\n3. Probabilities: 7.389 ÷ 11.107 = 0.665; 2.718 ÷ 11.107 = 0.245; 1 ÷ 11.107 = 0.090\n4. Check: 0.665 + 0.245 + 0.090 = 1\nPredicted class: the first (highest probability).",
      ask:["Sigmoid vs softmax"] };
  N["1.1.4"] = { q:"Explain the ReLU activation function.", m:3,
      a:"ReLU(x) = max(0, x)\n- Range: 0 to ∞.\n- Derivative: 1 for x > 0; 0 for x < 0.\nAdvantages:\n- No saturation for positive inputs: no vanishing gradient there.\n- Very cheap to compute.\n- Gives sparse activations.\n- Converges much faster than sigmoid or tanh.\nDisadvantage — dying ReLU: a neuron whose input is always negative outputs 0, gets zero gradient, and never recovers.\nUsed in: hidden layers of CNNs and deep networks (the default choice).",
      ask:["Why is ReLU preferred over the sigmoid in hidden layers?"] };
  N["1.1.5"] = { q:"Explain Leaky ReLU. Compare the activation functions.", m:5,
      a:"<p><b>Leaky ReLU:</b> f(x) = x for x &gt; 0; f(x) = 0.01 x for x ≤ 0. A small slope for negative inputs keeps the gradient non-zero, so neurons do not die.</p><table><tr><th>Function</th><th>Formula</th><th>Range</th><th>Problem</th><th>Used in</th></tr><tr><td>Sigmoid</td><td>1 ÷ (1 + e<sup>−x</sup>)</td><td>(0, 1)</td><td>Vanishing gradient</td><td>Binary output</td></tr><tr><td>Tanh</td><td>(e<sup>x</sup> − e<sup>−x</sup>) ÷ (e<sup>x</sup> + e<sup>−x</sup>)</td><td>(−1, 1)</td><td>Vanishing gradient</td><td>RNN hidden</td></tr><tr><td>Linear</td><td>x</td><td>(−∞, ∞)</td><td>No non-linearity</td><td>Regression output</td></tr><tr><td>ReLU</td><td>max(0, x)</td><td>[0, ∞)</td><td>Dying ReLU</td><td>Hidden layers</td></tr><tr><td>Leaky ReLU</td><td>max(0.01x, x)</td><td>(−∞, ∞)</td><td>Extra hyperparameter</td><td>Hidden layers</td></tr><tr><td>Softmax</td><td>e<sup>zi</sup> ÷ Σ e<sup>zj</sup></td><td>(0, 1), sum 1</td><td></td><td>Multi-class output</td></tr></table>",
      ask:["ReLU vs Leaky ReLU", "Compute each activation for x = −2 and x = 2"] };
  N["1.2.0"] = { q:"Explain the squared error loss.", m:3,
      a:"Squared error loss: L = ½ Σ (y − ŷ)² (for one example); mean squared error = (1 ÷ n) Σ (y − ŷ)² over n examples.\nUsed for: regression (real-valued output).\nExample: y = (1, 0), ŷ = (0.8, 0.3)\n1. Errors: 0.2 and −0.3\n2. Squares: 0.04 and 0.09\n3. L = ½ × 0.13 = 0.065\nGradient: ∂L/∂ŷ = −(y − ŷ) = ŷ − y.\nPenalises large errors heavily; sensitive to outliers.\nPoor for classification with a sigmoid output: the gradient becomes tiny when the neuron saturates.",
      ask:["Why is squared error not preferred for classification?"] };
  N["1.2.1"] = { q:"Explain the cross-entropy loss.", m:5,
      a:"Cross entropy — measures the difference between the true distribution y and the predicted distribution ŷ.\n- Binary: L = −[ y ln ŷ + (1 − y) ln (1 − ŷ) ]\n- Multi-class: L = −Σ yi ln ŷi. With a one-hot target this is −ln(ŷ of the true class).\nExample: the true class is class 1; softmax output (0.665, 0.245, 0.090).\nL = −ln(0.665) = 0.408\nIf the model were confident and right (0.99): L = 0.01. Confident and wrong (0.01): L = 4.6.\nUsed for: classification, with sigmoid or softmax output.\nWith softmax, the gradient at the output simplifies to ŷ − y.",
      trap:"Use the natural log, and only the probability of the true class matters for a one-hot target.",
      ask:["Compute the cross-entropy loss for the given output and target"] };
  N["1.3.0"] = { q:"How do you choose the output function and the loss function?", m:5,
      a:"<table><tr><th>Task</th><th>Output</th><th>Output activation</th><th>Loss</th></tr><tr><td>Regression</td><td>Real values</td><td>Linear</td><td>Squared error</td></tr><tr><td>Binary classification</td><td>One probability</td><td>Sigmoid</td><td>Binary cross entropy</td></tr><tr><td>Multi-class (one label)</td><td>Probability distribution</td><td>Softmax</td><td>Categorical cross entropy</td></tr><tr><td>Multi-label</td><td>Independent probabilities</td><td>Sigmoid on each output</td><td>Binary cross entropy on each</td></tr></table><p><b>Rule:</b> the output function must match the range of the target; the loss must match the output function.</p>",
      ask:["Which output and loss function would you use for the given problem?"] };
  N["1.4.0"] = [
    { q:"Explain learning with backpropagation.", m:5,
      a:"Backpropagation — an algorithm that computes the gradient of the loss with respect to every weight, by applying the chain rule backwards from the output layer.\nSteps:\n1. Forward pass: compute the activations of every layer and the output ŷ.\n2. Compute the loss.\n3. Output layer error: δ(out) = (ŷ − y) × f′(net). With softmax + cross entropy: δ = ŷ − y.\n4. Hidden layer error: δ(h) = f′(net h) × Σ δ(k) w(hk): the errors of the next layer, sent back through the weights.\n5. Gradient: ∂L/∂w(ij) = δ(j) × output of neuron i.\n6. Update: w = w − η × gradient.\n7. Repeat for all examples and epochs.\nChain rule: ∂L/∂w = ∂L/∂ŷ × ∂ŷ/∂net × ∂net/∂w.",
      ask:["Derive the weight update for the output layer"] },
    { q:"Numerical: one sigmoid neuron, x = 1, w = 0.5, b = 0, target 1, η = 0.5, squared error. Do one update.", m:5,
      a:"1. net = 0.5 × 1 + 0 = 0.5\n2. ŷ = σ(0.5) = 0.622\n3. L = ½ (1 − 0.622)² = 0.071\n4. δ = (ŷ − y) × ŷ (1 − ŷ) = (−0.378) × 0.622 × 0.378 = −0.089\n5. ∂L/∂w = δ × x = −0.089\n6. w = 0.5 − 0.5 × (−0.089) = 0.544\n7. b = 0 − 0.5 × (−0.089) = 0.044\nThe weight rises, so the output moves towards the target 1.",
      trap:"Keep the sign: the update is w − η × gradient.",
      ask:["Perform one iteration of backpropagation on the given network"] }
  ];
  N["1.5.0"] = { q:"Explain gradient descent.", m:5,
      a:"Gradient descent — an iterative method that minimises the loss by moving the weights in the direction opposite to the gradient.\nw(t+1) = w(t) − η × ∂L/∂w\n- η: the learning rate (step size).\nBatch (vanilla) gradient descent: the gradient is computed over the whole training set, then one update is made per epoch.\nExample: L = w², w = 4, η = 0.1.\n1. Gradient = 2w = 8\n2. w = 4 − 0.1 × 8 = 3.2\n3. Next: gradient 6.4 → w = 2.56 (moving towards the minimum at 0)\nProblems: slow on large data; can get stuck in local minima and on plateaus; one learning rate for all the weights.",
      ask:["Effect of the learning rate on convergence"] };
  N["1.5.1"] = { q:"Explain stochastic and mini-batch gradient descent. Compare with batch GD.", m:5,
      a:"<table><tr><th></th><th>Batch GD</th><th>Stochastic GD</th><th>Mini-batch GD</th></tr><tr><td>Examples per update</td><td>All N</td><td>1</td><td>B (32, 64, …)</td></tr><tr><td>Updates per epoch</td><td>1</td><td>N</td><td>N ÷ B</td></tr><tr><td>Path</td><td>Smooth</td><td>Noisy</td><td>In between</td></tr><tr><td>Speed per update</td><td>Slow</td><td>Fast</td><td>Fast (vectorised)</td></tr><tr><td>Memory</td><td>High</td><td>Low</td><td>Moderate</td></tr></table><p><b>Example:</b> N = 1000, batch size 100 → 10 updates per epoch. SGD → 1000. Batch → 1.</p><p>The noise of SGD helps escape shallow local minima. Mini-batch is the standard choice.</p>",
      ask:["How many weight updates are made in 5 epochs with N = 2000 and batch size 50? (200)"] };
  N["1.5.2"] = { q:"Explain momentum-based gradient descent.", m:5,
      a:"Problem — plain GD is slow on gentle slopes and oscillates in narrow valleys.\nIdea — add a fraction of the previous update, like a ball gathering speed downhill.\n- v(t) = γ v(t−1) + η ∇L(w(t))\n- w(t+1) = w(t) − v(t)\n- γ: momentum, usually 0.9.\nEffect:\n- Updates in the same direction add up: faster on flat regions.\n- Updates in opposite directions cancel: less oscillation.\nDisadvantage — it can overshoot the minimum and swing back and forth before settling.",
      ask:["GD vs momentum GD"] };
  N["1.5.3"] = { q:"Explain Nesterov Accelerated Gradient (NAG).", m:5,
      a:"Idea — look before you leap: first move by the momentum, then compute the gradient at that look-ahead point.\n- Look-ahead point: w′ = w(t) − γ v(t−1)\n- v(t) = γ v(t−1) + η ∇L(w′)\n- w(t+1) = w(t) − v(t)\nDifference from momentum: momentum computes the gradient at the current point; NAG computes it at the look-ahead point.\nEffect: it sees that it is about to overshoot and corrects earlier, so the oscillations are smaller and convergence is faster.",
      trap:"The only change from momentum is where the gradient is evaluated.",
      ask:["Momentum vs Nesterov"] };
  N["1.5.4"] = { q:"Explain AdaGrad.", m:5,
      a:"Idea — a separate, adaptive learning rate for each parameter: parameters that have had large gradients get smaller steps; rarely updated (sparse) ones get larger steps.\n- G(t) = G(t−1) + g(t)² (sum of all past squared gradients)\n- w(t+1) = w(t) − [η ÷ √(G(t) + ε)] × g(t)\n- ε: a small constant to avoid division by zero.\nAdvantage — no manual tuning of the learning rate; good for sparse data.\nDisadvantage — G only grows, so the learning rate keeps shrinking and learning eventually stops.",
      ask:["Why does the learning rate decay in AdaGrad?"] };
  N["1.5.5"] = { q:"Explain the Adam optimizer.", m:5,
      a:"Adam (Adaptive Moment Estimation) — combines momentum and RMSProp.\n- First moment (mean of gradients): m(t) = β1 m(t−1) + (1 − β1) g(t)\n- Second moment (mean of squared gradients): v(t) = β2 v(t−1) + (1 − β2) g(t)²\n- Bias correction: m̂ = m(t) ÷ (1 − β1^t); v̂ = v(t) ÷ (1 − β2^t)\n- Update: w(t+1) = w(t) − η × m̂ ÷ (√v̂ + ε)\nDefaults: β1 = 0.9, β2 = 0.999, ε = 10⁻⁸.\nWhy bias correction: m and v start at 0 and are too small in the first steps.\nAdvantages — fast convergence; adaptive rate per parameter; works well with little tuning. The default optimizer.",
      ask:["Why is Adam preferred?", "Adam vs RMSProp"] };
  N["1.5.6"] = { q:"Explain RMSProp. Compare the optimizers.", m:5,
      a:"<p><b>RMSProp:</b> fixes AdaGrad's shrinking learning rate by using a decaying average of the squared gradients instead of their sum.</p><ul><li>E(t) = β E(t−1) + (1 − β) g(t)², β = 0.9</li><li>w(t+1) = w(t) − [η ÷ √(E(t) + ε)] × g(t)</li></ul><table><tr><th>Optimizer</th><th>Idea</th><th>Weakness</th></tr><tr><td>GD</td><td>Step against the gradient</td><td>Slow; one learning rate</td></tr><tr><td>Momentum</td><td>Adds the past update</td><td>Overshoots</td></tr><tr><td>NAG</td><td>Gradient at the look-ahead point</td><td>Still one learning rate</td></tr><tr><td>AdaGrad</td><td>Rate ÷ √(sum of squared gradients)</td><td>Rate decays to zero</td></tr><tr><td>RMSProp</td><td>Rate ÷ √(moving average of squared gradients)</td><td>No momentum</td></tr><tr><td>Adam</td><td>Momentum + RMSProp + bias correction</td><td>More memory</td></tr></table>",
      ask:["AdaGrad vs RMSProp"] };
  N["1.6.0"] = { q:"Give an overview of overfitting.", m:5,
      a:"<table><tr><th></th><th>Underfitting</th><th>Good fit</th><th>Overfitting</th></tr><tr><td>Training error</td><td>High</td><td>Low</td><td>Very low</td></tr><tr><td>Test error</td><td>High</td><td>Low</td><td>High</td></tr><tr><td>Model</td><td>Too simple</td><td>Right</td><td>Too complex</td></tr><tr><td>Bias / variance</td><td>High bias</td><td>Balanced</td><td>High variance</td></tr></table><p><b>Overfitting:</b> the model memorises the training data, including its noise, and fails on new data.</p><p><b>Causes:</b> too many parameters; too little data; training for too long.</p><p><b>Sign:</b> the training loss keeps falling while the validation loss starts rising.</p><p><b>Remedy:</b> regularization: L1 / L2, dropout, early stopping, data augmentation, batch normalization; more data; a smaller model.</p>",
      ask:["How do you detect and prevent overfitting?"] };
  N["1.6.1"] = { q:"What are the types of biases (errors) a model can have?", m:3,
      a:"- Bias: error from wrong or too-simple assumptions. High bias → the model misses the pattern (underfitting).\n- Variance: error from sensitivity to the training sample. High variance → the model changes a lot with new data (overfitting).\n- Irreducible error: noise in the data; no model can remove it.\nExpected error = bias² + variance + irreducible error.\nDo not confuse with: the bias term b of a neuron; or data bias (sampling bias, selection bias), where the training data does not represent the real population.",
      ask:["Bias vs variance"] };
  N["1.6.2"] = { q:"Explain the bias-variance tradeoff.", m:5,
      a:"Expected error = bias² + variance + irreducible error.\n- Simple model: high bias, low variance.\n- Complex model: low bias, high variance.\nAs model complexity increases:\n- Bias falls.\n- Variance rises.\n- Total error first falls, then rises: a U-shaped curve.\nThe best model is at the bottom of the U, where the sum is smallest.\nTraining error always falls with complexity; test error follows the U.\nRegularization lowers the variance at the cost of a small increase in bias.",
      ask:["Draw the bias-variance curve and mark the optimal complexity"] };
  N["1.7.0"] = { q:"Explain L1 regularization.", m:3,
      a:"L1 (Lasso) — adds the sum of the absolute values of the weights to the loss.\nL(new) = L + λ Σ |w|\n- λ: regularization strength.\n- Gradient of the penalty: λ × sign(w): a constant push towards zero.\nEffect: many weights become exactly zero → a sparse model → automatic feature selection.\nUse: when only a few inputs are expected to matter.",
      ask:["Why does L1 give sparse weights?"] };
  N["1.7.1"] = { q:"Explain L2 regularization. Compare L1 and L2.", m:5,
      a:"<p><b>L2 (Ridge):</b> adds the sum of the squared weights to the loss: L(new) = L + (λ ÷ 2) Σ w².</p><p>Update: w = w − η (∂L/∂w + λ w) = (1 − ηλ) w − η ∂L/∂w. Every step shrinks the weights a little.</p><table><tr><th></th><th>L1</th><th>L2</th></tr><tr><td>Penalty</td><td>λ Σ |w|</td><td>(λ ÷ 2) Σ w²</td></tr><tr><td>Weights</td><td>Many exactly zero (sparse)</td><td>Small but non-zero</td></tr><tr><td>Feature selection</td><td>Yes</td><td>No</td></tr><tr><td>Penalty gradient</td><td>Constant: λ sign(w)</td><td>Proportional: λ w</td></tr><tr><td>Also called</td><td>Lasso</td><td>Ridge, weight decay</td></tr></table>",
      ask:["L1 vs L2 regularization"] };
  N["1.7.2"] = { q:"What is parameter sharing?", m:3,
      a:"Parameter sharing — forcing several parts of a model to use the same weights.\n- CNN: one filter (the same weights) is used at every position of the image.\n- RNN: the same weights are used at every time step.\nWhy it regularises:\n- Far fewer parameters → less overfitting.\n- Less memory.\n- CNN: a feature is detected wherever it appears (translation equivariance).\nExample: a 5 × 5 filter has 25 weights whatever the image size; a fully connected layer on a 32 × 32 image has 1024 weights per neuron.\nParameter tying: a softer form: the weights of two models are kept close with a penalty.",
      ask:["Parameter sharing vs parameter tying"] };
  N["1.7.3"] = { q:"Explain dropout.", m:5,
      a:"Dropout — during training, each neuron is switched off (output set to 0) at random with probability p, for each mini-batch.\nSteps:\n1. Training: drop each neuron with probability p (typically 0.5 for hidden layers, 0.2 for inputs).\n2. Forward and backward pass on the thinned network.\n3. Testing: use all the neurons; scale the outputs by (1 − p), or scale up by 1 ÷ (1 − p) during training (inverted dropout).\nWhy it works:\n- Neurons cannot rely on particular other neurons (no co-adaptation).\n- It is like training many thinned networks and averaging them (an ensemble).\nEffect: less overfitting; training takes longer.",
      trap:"Dropout is used only during training, never at test time.",
      ask:["How does dropout prevent overfitting?"] };
  N["1.7.4"] = { q:"What is weight decay?", m:3,
      a:"Weight decay — shrinking every weight a little at each update, so that the weights stay small.\nw(t+1) = (1 − ηλ) w(t) − η ∂L/∂w\n- (1 − ηλ) is slightly less than 1: the decay factor.\nFor plain gradient descent, weight decay is the same as L2 regularization.\nExample: η = 0.1, λ = 0.01 → each step multiplies the weight by 0.999 before the gradient step.\nWhy small weights: the function is smoother and less sensitive to noise in the input, so it generalises better.",
      ask:["Relation between weight decay and L2 regularization"] };
  N["1.7.5"] = { q:"Explain batch normalization.", m:5,
      a:"Batch normalization — normalising the inputs of a layer over each mini-batch.\nFor a mini-batch:\n1. Mean: μ = (1 ÷ m) Σ x\n2. Variance: σ² = (1 ÷ m) Σ (x − μ)²\n3. Normalise: x̂ = (x − μ) ÷ √(σ² + ε)\n4. Scale and shift: y = γ x̂ + β (γ and β are learned)\nWhy: the distribution of each layer's inputs keeps changing during training (internal covariate shift).\nAdvantages:\n- Faster training; higher learning rates can be used.\n- Less sensitive to weight initialisation.\n- Reduces vanishing gradients.\n- Slight regularising effect.\nAt test time: the running mean and variance from training are used.",
      ask:["Where is batch normalization placed in a network?"] };
  N["1.7.6"] = { q:"Explain early stopping.", m:3,
      a:"Early stopping — stop training when the validation error stops improving, before the model overfits.\nSteps:\n1. Split off a validation set.\n2. After each epoch, compute the validation error.\n3. Save the model whenever the validation error is the lowest so far.\n4. If it has not improved for p epochs (the patience), stop.\n5. Return the saved best model.\nTraining error keeps falling; validation error falls, then rises. Stop at the turning point.\nAdvantage — simple; no change to the model; saves training time.",
      ask:["What is patience in early stopping?"] };
  N["1.7.7"] = { q:"Explain data augmentation.", m:3,
      a:"Data augmentation — creating new training examples by applying label-preserving transformations to the existing ones.\nFor images:\n- Flip (horizontal)\n- Rotate\n- Crop and scale (zoom)\n- Shift (translate)\n- Change brightness and contrast\n- Add noise\nFor text: synonym replacement, back-translation.\nWhy: more and more varied data → less overfitting; the model becomes invariant to these changes.\nCaution: the label must stay correct: flipping a '6' vertically makes a '9'.",
      ask:["Give examples of data augmentation for images"] };
  N["1.7.8"] = { q:"How does adding noise to the input and output act as regularization?", m:3,
      a:"Noise at the input:\n- Add small random noise (Gaussian) to each input during training.\n- The model must give the same output for slightly different inputs, so it learns a smoother function.\n- For a linear model with squared error, this is equivalent to L2 regularization.\n- Basis of the denoising autoencoder.\nNoise at the output (label smoothing):\n- Labels may be wrong; a hard target of 1 pushes the model to be over-confident.\n- Replace 1 with 1 − ε and 0 with ε ÷ (k − 1).\n- Example: ε = 0.1, 3 classes: (1, 0, 0) → (0.9, 0.05, 0.05).\nNoise can also be added to the weights.",
      ask:["What is label smoothing?"] };

  /* ------------------------------------------------ Module 3 */
  N["2.0.0"] = { q:"Explain the convolution operation. Convolve the input [[1,2,3],[4,5,6],[7,8,9]] with the filter [[1,0],[0,1]].", m:5,
      a:"<p><b>Convolution:</b> slide a small filter (kernel) over the input; at each position multiply element by element and add. The result is a feature map.</p><p>Output size = 3 − 2 + 1 = 2 × 2.</p><table><tr><th>Position</th><th>Calculation</th><th>Value</th></tr><tr><td>Top-left</td><td>1×1 + 2×0 + 4×0 + 5×1</td><td>6</td></tr><tr><td>Top-right</td><td>2×1 + 3×0 + 5×0 + 6×1</td><td>8</td></tr><tr><td>Bottom-left</td><td>4×1 + 5×0 + 7×0 + 8×1</td><td>12</td></tr><tr><td>Bottom-right</td><td>5×1 + 6×0 + 8×0 + 9×1</td><td>14</td></tr></table><p><b>Feature map:</b> [[6, 8], [12, 14]]</p><p>Each filter detects one feature (an edge, a corner). The filter values are learned.</p>",
      ask:["Apply the given 3 × 3 filter to the given image"] };
  N["2.0.1"] = { q:"What is padding? Explain valid and same padding.", m:3,
      a:"Padding — adding rows and columns of zeros around the input before convolution.\nWhy:\n- Without padding the output shrinks at every layer.\n- Border pixels are used less than centre pixels.\nTypes:\n- Valid: no padding (p = 0). Output = n − f + 1.\n- Same: padding so that output size = input size (stride 1). p = (f − 1) ÷ 2.\n- Full: p = f − 1. Output = n + f − 1.\nExample: n = 5, f = 3. Valid → 3 × 3. Same (p = 1) → 5 × 5. Full (p = 2) → 7 × 7.",
      ask:["Find the padding needed to keep the output size equal to the input size"] };
  N["2.0.2"] = { q:"What is stride?", m:2,
      a:"Stride — the number of pixels the filter moves at each step.\n- Stride 1: moves one pixel at a time; large output.\n- Stride 2: skips every other position; the output is about half the size.\nA larger stride reduces the size of the feature map and the computation (down-sampling), but loses detail.\nExample: n = 7, f = 3, p = 0. Stride 1 → 5 × 5. Stride 2 → 3 × 3.",
      ask:["Effect of stride on the output size"] };
  N["2.0.3"] = { q:"State the relation between input size, output size and filter size.", m:3,
      a:"Output size O = (n + 2p − f) ÷ s + 1 (take the floor)\n- n: input size\n- f: filter size\n- p: padding\n- s: stride\nOutput depth = number of filters K.\nSo the output volume is O × O × K.\nNumber of parameters in a conv layer = (f × f × input depth + 1) × K.",
      trap:"The +1 in the parameter count is the bias of each filter.",
      ask:["Derive the output size formula"] };
  N["2.0.4"] = { q:"Numerical: input 32 × 32 × 3, six 5 × 5 filters, stride 1, no padding. Find the output size and the number of parameters.", m:5,
      a:"1. O = (n + 2p − f) ÷ s + 1 = (32 + 0 − 5) ÷ 1 + 1 = 28\n2. Output volume = 28 × 28 × 6\n3. Parameters per filter = 5 × 5 × 3 + 1 = 76\n4. Total parameters = 76 × 6 = 456\nMore:\n- Input 227, f = 11, s = 4, p = 0 → (227 − 11) ÷ 4 + 1 = 55 (AlexNet conv 1).\n- Input 28, max pool 2 × 2, stride 2 → (28 − 2) ÷ 2 + 1 = 14. Pooling has 0 parameters.",
      ask:["Compute the output size and parameters for each layer of the given CNN"] };
  N["2.1.0"] = { q:"Explain the convolution layer.", m:5,
      a:"Convolution layer — the main building block of a CNN: a set of learnable filters, each producing one feature map.\n- Each filter is small in width and height but covers the full depth of the input.\n- Local connectivity: each output neuron sees only a small patch (its receptive field).\n- Weight sharing: the same filter is used at every position.\n- An activation (ReLU) is applied to the feature map.\nHyperparameters: number of filters K, filter size f, stride s, padding p.\nWhat it learns: early layers → edges and colours; middle layers → textures and parts; deep layers → objects.\nOutput: O × O × K with O = (n + 2p − f) ÷ s + 1.",
      ask:["What is a receptive field?", "What is a feature map?"] };
  N["2.1.1"] = { q:"Explain the pooling layer. Apply 2 × 2 max pooling (stride 2) to [[1,3,2,4],[5,6,7,8],[3,2,1,0],[1,2,3,4]].", m:5,
      a:"<p><b>Pooling:</b> down-samples a feature map by summarising each small window with one number.</p><ul><li><b>Max pooling:</b> the largest value in the window.</li><li><b>Average pooling:</b> the mean of the window.</li><li><b>Global average pooling:</b> one value per feature map.</li></ul><p><b>Why:</b> smaller feature maps → fewer parameters and less computation; small shifts in the input do not change the output; less overfitting.</p><p>Pooling has no learnable parameters.</p><table><tr><th>Window</th><th>Values</th><th>Max</th><th>Average</th></tr><tr><td>Top-left</td><td>1, 3, 5, 6</td><td>6</td><td>3.75</td></tr><tr><td>Top-right</td><td>2, 4, 7, 8</td><td>8</td><td>5.25</td></tr><tr><td>Bottom-left</td><td>3, 2, 1, 2</td><td>3</td><td>2</td></tr><tr><td>Bottom-right</td><td>1, 0, 3, 4</td><td>4</td><td>2</td></tr></table><p><b>Max-pooled output:</b> [[6, 8], [3, 4]]</p>",
      ask:["Max pooling vs average pooling"] };
  N["2.1.2"] = { q:"What is weight sharing in a CNN?", m:3,
      a:"Weight sharing — every position of a feature map is computed with the same filter weights.\nBenefits:\n- Far fewer parameters.\n- A feature learned in one place is detected everywhere (translation equivariance).\n- Less overfitting; faster training.\nExample: input 32 × 32 × 3, six 5 × 5 filters, output 28 × 28 × 6.\n- With sharing: (5 × 5 × 3 + 1) × 6 = 456 parameters.\n- Without sharing (each output neuron has its own weights): 28 × 28 × 6 × 76 = 357,504 parameters.\nSparse connectivity + weight sharing are the two ideas that make CNNs efficient.",
      ask:["How does a CNN reduce the number of parameters?"] };
  N["2.2.0"] = { q:"Compare a fully connected neural network with a CNN.", m:5,
      a:"<table><tr><th></th><th>Fully connected NN</th><th>CNN</th></tr><tr><td>Connections</td><td>Every neuron to every neuron of the next layer</td><td>Each neuron to a small local patch</td></tr><tr><td>Weights</td><td>Separate for every connection</td><td>Shared across positions</td></tr><tr><td>Parameters</td><td>Very many</td><td>Few</td></tr><tr><td>Input</td><td>Flattened vector; spatial structure is lost</td><td>2D / 3D grid; structure is kept</td></tr><tr><td>Shift of the object</td><td>Must be re-learned</td><td>Handled (translation equivariance)</td></tr><tr><td>Overfitting on images</td><td>High</td><td>Lower</td></tr><tr><td>Best for</td><td>Tabular data</td><td>Images, video</td></tr></table><p><b>Example:</b> a 224 × 224 × 3 image into a hidden layer of 1000 neurons needs 150,528 × 1000 ≈ 150 million weights. A conv layer with 64 filters of 3 × 3 needs (27 + 1) × 64 = 1792.</p><p><b>CNN layout:</b> input → [conv → ReLU → pool] × n → flatten → fully connected → softmax.</p>",
      ask:["Why are CNNs preferred for image data?"] };
  N["2.3.0"] = { q:"What are the variants of the basic convolution function?", m:5,
      a:"<table><tr><th>Variant</th><th>Idea</th></tr><tr><td>Full convolution</td><td>Enough zero padding for every overlap; the output is larger than the input: n + f − 1</td></tr><tr><td>Strided convolution</td><td>The filter moves s pixels at a time; down-samples</td></tr><tr><td>Unshared convolution (locally connected)</td><td>Local connections like a convolution, but every position has its own weights: no sharing</td></tr><tr><td>Tiled convolution</td><td>Cycles through a small set of filters, so that neighbouring positions use different filters</td></tr><tr><td>Dilated (atrous) convolution</td><td>Gaps between the filter elements; a larger receptive field with the same number of weights</td></tr><tr><td>Transposed convolution</td><td>Up-samples a feature map; used in decoders and GAN generators</td></tr><tr><td>1 × 1 convolution</td><td>Changes the number of channels</td></tr></table><p>The class deck stresses the first, third and fourth: full, unshared and tiled.</p>",
      ask:["Tiled vs unshared convolution"] };
  N["2.4.0"] = { q:"Explain the LeNet-5 architecture.", m:5,
      a:"<p>LeNet-5 (LeCun, 1998): handwritten digit recognition (MNIST). About 60,000 parameters.</p><table><tr><th>Layer</th><th>Operation</th><th>Output</th></tr><tr><td>Input</td><td></td><td>32 × 32 × 1</td></tr><tr><td>C1</td><td>6 filters, 5 × 5</td><td>28 × 28 × 6</td></tr><tr><td>S2</td><td>Average pooling 2 × 2, stride 2</td><td>14 × 14 × 6</td></tr><tr><td>C3</td><td>16 filters, 5 × 5</td><td>10 × 10 × 16</td></tr><tr><td>S4</td><td>Average pooling 2 × 2, stride 2</td><td>5 × 5 × 16</td></tr><tr><td>C5</td><td>120 filters, 5 × 5 (fully connected)</td><td>120</td></tr><tr><td>F6</td><td>Fully connected</td><td>84</td></tr><tr><td>Output</td><td>Fully connected</td><td>10 classes</td></tr></table><p>Activation: tanh / sigmoid. Pattern: conv → pool → conv → pool → FC → FC → output.</p>",
      trap:"LeNet uses average pooling and tanh, not max pooling and ReLU.",
      ask:["Draw the LeNet architecture with the size of each layer"] };
  N["2.5.0"] = { q:"Explain the AlexNet architecture. What were its innovations?", m:10,
      a:"<p>AlexNet (Krizhevsky, 2012): won ImageNet (1000 classes). 8 learned layers: 5 conv + 3 fully connected. About 60 million parameters.</p><table><tr><th>Layer</th><th>Operation</th><th>Output</th></tr><tr><td>Input</td><td></td><td>227 × 227 × 3</td></tr><tr><td>Conv 1</td><td>96 filters, 11 × 11, stride 4</td><td>55 × 55 × 96</td></tr><tr><td>Max pool</td><td>3 × 3, stride 2</td><td>27 × 27 × 96</td></tr><tr><td>Conv 2</td><td>256 filters, 5 × 5, pad 2</td><td>27 × 27 × 256</td></tr><tr><td>Max pool</td><td>3 × 3, stride 2</td><td>13 × 13 × 256</td></tr><tr><td>Conv 3</td><td>384 filters, 3 × 3, pad 1</td><td>13 × 13 × 384</td></tr><tr><td>Conv 4</td><td>384 filters, 3 × 3, pad 1</td><td>13 × 13 × 384</td></tr><tr><td>Conv 5</td><td>256 filters, 3 × 3, pad 1</td><td>13 × 13 × 256</td></tr><tr><td>Max pool</td><td>3 × 3, stride 2</td><td>6 × 6 × 256</td></tr><tr><td>FC 6, FC 7</td><td>Fully connected + dropout</td><td>4096 each</td></tr><tr><td>FC 8</td><td>Softmax</td><td>1000</td></tr></table><p><b>Innovations:</b> ReLU instead of tanh; dropout in the FC layers; data augmentation; overlapping max pooling; local response normalization; training on two GPUs.</p>",
      ask:["LeNet vs AlexNet", "Why did AlexNet use ReLU?"] };

  /* ------------------------------------------------ Module 4 */
  N["3.0.0"] = { q:"What is an autoencoder? Explain its architecture.", m:5,
      a:"Autoencoder — an unsupervised neural network trained to reproduce its input at its output.\nx → Encoder → h (code) → Decoder → x̂\n- Encoder: h = f(W x + b): compresses the input into a code (latent representation).\n- Bottleneck / code layer: the compressed representation.\n- Decoder: x̂ = g(W′ h + b′): rebuilds the input from the code.\n- Loss: reconstruction error L = ‖x − x̂‖² (or cross entropy for binary inputs).\nNo labels are needed: the input is its own target.\nTrained by backpropagation.\nUses: dimensionality reduction, denoising, compression, anomaly detection, pre-training.",
      ask:["Why is an autoencoder called unsupervised (self-supervised)?"] };
  N["3.1.0"] = { q:"What is a linear autoencoder? How is it related to PCA?", m:3,
      a:"Linear autoencoder — an autoencoder with linear activations in the encoder and decoder, and squared error loss.\nh = W x; x̂ = W′ h\nRelation to PCA: an undercomplete linear autoencoder with squared error learns the same subspace as PCA: the code spans the top principal components.\nConditions for the equivalence: linear encoder, linear decoder, squared error loss, normalised inputs.\nLimit: it can capture only linear relationships. Non-linear activations give a more powerful, non-linear generalisation of PCA.",
      ask:["Autoencoder vs PCA"] };
  N["3.1.1"] = { q:"What is an undercomplete autoencoder?", m:3,
      a:"Undercomplete autoencoder — the code layer has fewer neurons than the input: dim(h) < dim(x).\n- The network cannot simply copy the input; it must keep only the most important features.\n- Loss: L(x, g(f(x))): reconstruction error alone; no extra penalty.\nExample: 784 → 128 → 32 → 128 → 784.\nUse: dimensionality reduction, compression, feature learning.\nRisk: if the encoder and decoder are too powerful, it can still memorise without learning useful features.",
      ask:["Undercomplete vs overcomplete autoencoder"] };
  N["3.1.2"] = { q:"What is an overcomplete autoencoder?", m:3,
      a:"Overcomplete autoencoder — the code layer has as many or more neurons than the input: dim(h) ≥ dim(x).\nProblem: it can learn the identity function (copy the input to the code and back), with zero reconstruction error and no useful features.\nSolution: regularise it, so that copying is not possible:\n- Sparse autoencoder: penalise the activations.\n- Denoising autoencoder: corrupt the input.\n- Contractive autoencoder: penalise the sensitivity to the input.\nWith regularization, an overcomplete code can learn rich features.",
      trap:"An overcomplete autoencoder is useful only when it is regularised.",
      ask:["Why does an overcomplete autoencoder need regularization?"] };
  N["3.1.3"] = { q:"Explain the denoising autoencoder.", m:5,
      a:"Denoising autoencoder — trained to rebuild the clean input from a corrupted version of it.\nx → corrupt → x̃ → Encoder → h → Decoder → x̂, with loss L(x, x̂) against the clean x.\nSteps:\n1. Take a clean input x.\n2. Corrupt it: add Gaussian noise, or set random inputs to zero (masking), to get x̃.\n3. Encode x̃; decode to x̂.\n4. Minimise ‖x − x̂‖², comparing with the clean x.\nWhy: it cannot copy the input, because the input it sees is noisy. It must learn the structure of the data to remove the noise.\nUse: image denoising; robust feature learning; works with overcomplete codes.",
      trap:"The loss compares the output with the clean input, not the noisy one.",
      ask:["How does a denoising autoencoder avoid learning the identity function?"] };
  N["3.1.4"] = { q:"Explain the sparse autoencoder.", m:5,
      a:"Sparse autoencoder — adds a penalty so that only a few hidden neurons are active for any input.\nLoss = reconstruction error + sparsity penalty\n- L1 penalty: L = ‖x − x̂‖² + λ Σ |h|\n- KL-divergence penalty: L = ‖x − x̂‖² + β Σ KL(ρ ‖ ρ̂j)\n- ρ: the target average activation (small, e.g. 0.05). ρ̂j: the actual average activation of hidden neuron j.\n- KL(ρ ‖ ρ̂) = ρ ln(ρ ÷ ρ̂) + (1 − ρ) ln((1 − ρ) ÷ (1 − ρ̂)); zero when ρ̂ = ρ.\nEffect: each neuron responds to a specific feature. The code layer can be larger than the input and still learn useful features.\nUse: feature extraction for classification.",
      ask:["What is the sparsity constraint?"] };
  N["3.1.5"] = { q:"Explain the contractive autoencoder.", m:5,
      a:"Contractive autoencoder — adds a penalty that makes the code insensitive to small changes in the input.\nLoss = ‖x − x̂‖² + λ ‖J‖²F\n- J: the Jacobian of the encoder: ∂h/∂x.\n- ‖J‖²F = Σ (∂hj/∂xi)²: the squared Frobenius norm.\nEffect: nearby inputs are mapped to nearby (contracted) codes; the code changes only along the directions in which the data really varies.\nCompared with the denoising autoencoder: denoising makes the reconstruction robust to noise; contractive makes the encoder (the features) robust.\nCost: computing the Jacobian is expensive.",
      ask:["Denoising vs contractive autoencoder"] };
  N["3.2.0"] = { q:"What is the bottleneck of an autoencoder? What is its impact?", m:5,
      a:"<p><b>Bottleneck:</b> the code layer, the narrowest layer between the encoder and the decoder. All the information must pass through it.</p><table><tr><th>Bottleneck size</th><th>Effect</th></tr><tr><td>Too small</td><td>Too much is lost: poor, blurry reconstruction (underfitting)</td></tr><tr><td>Right size</td><td>Keeps the important features; good compression and reconstruction</td></tr><tr><td>Too large</td><td>Copies the input; learns nothing useful (identity function)</td></tr></table><p><b>Impact:</b></p><ul><li>Forces compression: only the most important features survive.</li><li>Sets the compression ratio: 784 → 32 is about 24 : 1.</li><li>Acts as a regulariser.</li><li>Trade-off: a smaller code gives more compression but a higher reconstruction error.</li></ul>",
      ask:["How do you choose the size of the code layer?"] };
  N["3.3.0"] = { q:"How are autoencoders used for image compression?", m:3,
      a:"1. Train an undercomplete (usually convolutional) autoencoder on images.\n2. Compress: pass the image through the encoder; store or send only the small code.\n3. Decompress: pass the code through the decoder to rebuild the image.\nExample: a 28 × 28 image (784 values) → a code of 32 values → rebuilt 784 values.\nProperties:\n- Lossy: the rebuilt image is not exactly the original.\n- Data-specific: it compresses well only the kind of images it was trained on.\n- Learned from data, unlike JPEG, which is hand-designed.",
      ask:["Why is autoencoder compression lossy and data-specific?"] };
  N["3.3.1"] = { q:"How are autoencoders used for image denoising?", m:3,
      a:"Uses a denoising autoencoder.\n1. Take clean images; add noise (Gaussian, salt-and-pepper) to make noisy copies.\n2. Train: input = noisy image, target = clean image.\n3. Loss: ‖clean − output‖².\n4. Use: give a new noisy image; the output is the cleaned image.\nWhy it works: noise is random and cannot pass through the bottleneck; the structure of the image can.\nApplications: medical images, old photographs, low-light pictures, scanned documents.",
      ask:["Explain image denoising with a neat diagram"] };
  N["3.3.2"] = { q:"How are autoencoders used for dimensionality reduction?", m:3,
      a:"1. Train an undercomplete autoencoder.\n2. Throw away the decoder.\n3. Use the encoder output (the code) as the low-dimensional representation of each input.\nExample: 784-dimensional images → a 2-dimensional code that can be plotted.\nAutoencoder vs PCA:\n- PCA: linear; fast; components are ordered and uncorrelated.\n- Autoencoder: non-linear; captures complex structure; needs training and more data.\nUses: visualisation, faster training of later models, information retrieval (similar items have similar codes).",
      ask:["Autoencoder vs PCA for dimensionality reduction"] };

  /* ------------------------------------------------ Module 5 */
  N["4.0.0"] = { q:"What is a sequence learning problem? Why can feedforward networks not handle it?", m:5,
      a:"Sequence learning problem — the input or output (or both) is a sequence in which the order matters and each element depends on the earlier ones.\nExamples:\n- Next-word prediction (text)\n- Speech recognition\n- Machine translation\n- Stock price prediction (time series)\n- Video analysis\nWhy feedforward networks / CNNs fail:\n- They need inputs of a fixed size; sequences vary in length.\n- They treat inputs as independent: no memory of earlier inputs.\n- No sharing of parameters across time steps.\nTypes: one to many (image captioning), many to one (sentiment analysis), many to many (translation, POS tagging).",
      ask:["Types of sequence problems with examples"] };
  N["4.0.1"] = { q:"What is unfolding a computational graph?", m:3,
      a:"A recurrent network has a loop: h(t) = f(h(t−1), x(t); θ).\nUnfolding — drawing that loop as a chain, one copy of the network for each time step:\nx1 → h1 → h2 → h3 → … with x2, x3 feeding in and y1, y2, y3 coming out.\n- Each copy uses the same parameters θ (U, W, V).\n- h3 = f(f(f(h0, x1), x2), x3).\nWhy it is useful:\n- The unfolded graph has no loops, so ordinary backpropagation can be applied (BPTT).\n- The same model works for a sequence of any length.\n- It shows how information and gradients flow across time.",
      ask:["Draw the unfolded graph of an RNN for three time steps"] };
  N["4.1.0"] = { q:"Explain the Recurrent Neural Network (RNN).", m:5,
      a:"RNN — a network with a hidden state that is passed from one time step to the next, giving it memory.\nAt each time step t:\n- h(t) = tanh(U x(t) + W h(t−1) + b)\n- y(t) = softmax(V h(t) + c)\n- U: input-to-hidden weights; W: hidden-to-hidden weights; V: hidden-to-output weights.\n- The same U, W, V are used at every step (parameter sharing).\nLoss: the sum of the losses at all the time steps.\nTrained by backpropagation through time.\nAdvantages — handles sequences of any length; remembers the past.\nLimitations — vanishing and exploding gradients; cannot remember long-term dependencies; slow (no parallelism).",
      ask:["Draw the architecture of an RNN", "Applications of RNNs"] };
  N["4.1.1"] = { q:"Explain the Bidirectional RNN.", m:3,
      a:"Bidirectional RNN — two RNNs over the same sequence: one reads it forward (left to right), the other backward (right to left).\n- Forward state: h→(t) = f(x(t), h→(t−1))\n- Backward state: h←(t) = f(x(t), h←(t+1))\n- Output: y(t) = g([h→(t), h←(t)]): both states are combined.\nWhy: the output at time t can use both the past and the future context.\nExample: 'He said Teddy bears are on sale' vs 'He said Teddy Roosevelt was a president': the words after 'Teddy' decide whether it is a name.\nUse: named entity recognition, POS tagging, speech recognition.\nLimit: the whole sequence must be available first, so it cannot be used for real-time prediction.",
      ask:["RNN vs bidirectional RNN"] };
  N["4.2.0"] = { q:"Explain Backpropagation Through Time (BPTT).", m:5,
      a:"BPTT — backpropagation applied to the unfolded RNN.\nSteps:\n1. Unfold the RNN over all the time steps.\n2. Forward pass: compute h(t), y(t) and the loss L(t) at each step.\n3. Total loss L = Σ L(t).\n4. Backward pass: send the error back from the last time step to the first.\n5. Since the weights are shared, add up the gradients from all the time steps.\n6. Update U, W, V.\nGradient for W:\n∂L(t)/∂W = Σ (k = 1 to t) ∂L(t)/∂y(t) × ∂y(t)/∂h(t) × ∂h(t)/∂h(k) × ∂h(k)/∂W\nwhere ∂h(t)/∂h(k) is a product of (t − k) terms, one per step.\nThis long product is the cause of vanishing and exploding gradients.",
      ask:["How does BPTT differ from ordinary backpropagation?"] };
  N["4.2.1"] = { q:"Explain the vanishing and exploding gradient problems.", m:5,
      a:"<p>In BPTT the gradient contains ∂h(t)/∂h(k), a product of (t − k) factors, each = W × tanh′.</p><table><tr><th></th><th>Vanishing gradient</th><th>Exploding gradient</th></tr><tr><td>Cause</td><td>Factors less than 1 multiplied many times</td><td>Factors greater than 1 multiplied many times</td></tr><tr><td>Gradient</td><td>Shrinks towards 0</td><td>Grows towards infinity</td></tr><tr><td>Effect</td><td>Early time steps do not learn; long-term dependencies are forgotten</td><td>Huge, unstable updates; NaN loss</td></tr><tr><td>Remedy</td><td>LSTM / GRU; ReLU; good initialisation</td><td>Gradient clipping; truncated BPTT</td></tr></table><p><b>Example:</b> 0.9<sup>50</sup> = 0.005; 1.1<sup>50</sup> = 117.</p><p><b>Gradient clipping:</b> if ‖g‖ &gt; threshold, set g = threshold × g ÷ ‖g‖.</p>",
      ask:["Why can an RNN not learn long-term dependencies?", "What is gradient clipping?"] };
  N["4.2.2"] = { q:"What is Truncated BPTT?", m:3,
      a:"Truncated BPTT — backpropagating the error only a fixed number of time steps back (k), instead of all the way to the start.\nSteps:\n1. Run the forward pass over the sequence, carrying the hidden state.\n2. Every k1 steps, backpropagate for only the last k2 steps.\n3. Update the weights; continue forward.\nAdvantages:\n- Much less computation and memory for long sequences.\n- Reduces the exploding gradient problem.\nDisadvantage: dependencies longer than k steps cannot be learned.\nExample: a sequence of 1000 steps with k = 20: the gradients flow back 20 steps at a time.",
      ask:["BPTT vs truncated BPTT"] };
  N["4.3.0"] = [
    { q:"What is an LSTM? Why is it needed?", m:5,
      a:"LSTM (Long Short-Term Memory) — an RNN with a cell state and gates that control what is forgotten, stored and output, so that it can remember over long sequences.\nWhy: a plain RNN rewrites its whole state at every step, and its gradients vanish. Like a whiteboard that is completely overwritten each time.\nThe LSTM does three things selectively:\n- Selective forget (forget gate): erase what is no longer needed.\n- Selective read (input gate): take in only the useful part of the new information.\n- Selective write (output gate): pass on only the part of the state that is needed.\nCell state c(t): the long-term memory. Hidden state h(t): the short-term memory / output.\nThe cell state is changed only by addition, so the gradient flows back without vanishing.",
      ask:["RNN vs LSTM", "Draw the LSTM cell"] },
    { q:"Explain selective read in an LSTM.", m:3,
      a:"Selective read — taking only part of the new information into the cell state. Done by the input gate.\n- Candidate: c̃(t) = tanh(W h(t−1) + U x(t) + b)\n- Input gate: i(t) = σ(Wi h(t−1) + Ui x(t) + bi)\n- What is read: i(t) ⊙ c̃(t)\nThe gate is a sigmoid: each value is between 0 (ignore) and 1 (read fully).\nExample: reading a review, the gate lets in 'excellent' and ignores 'the'.",
      ask:["Role of the input gate"] }
  ];
  N["4.3.1"] = { q:"Explain selective write in an LSTM.", m:3,
      a:"Selective write — passing only part of the cell state out as the hidden state. Done by the output gate.\n- Output gate: o(t) = σ(Wo h(t−1) + Uo x(t) + bo)\n- Hidden state: h(t) = o(t) ⊙ tanh(c(t))\nThe cell holds everything remembered so far; the output gate decides which part is relevant for the current output and for the next step.\nExample: the cell remembers the subject of the sentence and its number; only the number is written out when the verb has to be chosen.",
      ask:["Role of the output gate"] };
  N["4.3.2"] = { q:"Explain selective forget in an LSTM. Write the full set of LSTM equations.", m:5,
      a:"<p><b>Selective forget:</b> erasing part of the old cell state. Done by the forget gate: f(t) = σ(Wf h(t−1) + Uf x(t) + bf). What is kept: f(t) ⊙ c(t−1).</p><table><tr><th>Step</th><th>Equation</th></tr><tr><td>Forget gate</td><td>f(t) = σ(Wf h(t−1) + Uf x(t) + bf)</td></tr><tr><td>Input gate</td><td>i(t) = σ(Wi h(t−1) + Ui x(t) + bi)</td></tr><tr><td>Output gate</td><td>o(t) = σ(Wo h(t−1) + Uo x(t) + bo)</td></tr><tr><td>Candidate</td><td>c̃(t) = tanh(W h(t−1) + U x(t) + b)</td></tr><tr><td>Cell state</td><td>c(t) = f(t) ⊙ c(t−1) + i(t) ⊙ c̃(t)</td></tr><tr><td>Hidden state</td><td>h(t) = o(t) ⊙ tanh(c(t))</td></tr></table><p>Gates use the sigmoid (0 to 1); the candidate and the output use tanh.</p><p><b>Why gradients do not vanish:</b> c(t) depends on c(t−1) through an addition and the forget gate; if f ≈ 1 the gradient passes unchanged.</p>",
      trap:"Three gates use the sigmoid. Only the candidate and the final squashing use tanh.",
      ask:["How does the LSTM solve the vanishing gradient problem?"] };
  N["4.3.3"] = { q:"Explain the Gated Recurrent Unit (GRU). Compare it with the LSTM.", m:5,
      a:"<p><b>GRU:</b> a simpler gated RNN with two gates and no separate cell state.</p><ul><li>Update gate: z(t) = σ(Wz h(t−1) + Uz x(t))</li><li>Reset gate: r(t) = σ(Wr h(t−1) + Ur x(t))</li><li>Candidate: h̃(t) = tanh(W (r(t) ⊙ h(t−1)) + U x(t))</li><li>State: h(t) = (1 − z(t)) ⊙ h(t−1) + z(t) ⊙ h̃(t)</li></ul><p>Update gate: how much of the old state to keep (forget + input in one). Reset gate: how much of the past to use for the candidate.</p><table><tr><th></th><th>LSTM</th><th>GRU</th></tr><tr><td>Gates</td><td>3: forget, input, output</td><td>2: update, reset</td></tr><tr><td>States</td><td>Cell state + hidden state</td><td>Hidden state only</td></tr><tr><td>Parameters</td><td>More</td><td>Fewer; trains faster</td></tr><tr><td>Performance</td><td>Better on long sequences, large data</td><td>Similar on small data</td></tr></table>",
      ask:["LSTM vs GRU"] };

  /* ------------------------------------------------ Module 6 */
  N["5.0.0"] = [
    { q:"Explain the architecture of a Generative Adversarial Network (GAN).", m:5,
      a:"GAN (Goodfellow, 2014) — two networks trained against each other.\n- Generator G: takes random noise z and produces a fake sample G(z). Goal: fool the discriminator.\n- Discriminator D: takes a sample and outputs the probability that it is real. Goal: tell real from fake.\nNoise z → Generator → fake image → Discriminator ← real image; Discriminator → real / fake\nAnalogy: a counterfeiter (G) and the police (D).\nObjective (minimax game):\nmin over G, max over D: V(D, G) = E[log D(x)] + E[log(1 − D(G(z)))]\n- D wants D(x) → 1 and D(G(z)) → 0.\n- G wants D(G(z)) → 1.\nAt equilibrium: the fake data looks like the real data and D outputs 0.5 everywhere.",
      ask:["Role of the generator and the discriminator", "Draw the block diagram of a GAN"] },
    { q:"How is a GAN trained? What are its problems?", m:5,
      a:"Training (alternating):\n1. Sample a mini-batch of real data x and of noise z.\n2. Generate fakes G(z).\n3. Train D: update D to maximise log D(x) + log(1 − D(G(z))). G is frozen.\n4. Train G: sample new noise; update G to maximise log D(G(z)). D is frozen.\n5. Repeat.\nProblems:\n- Mode collapse: G produces only a few kinds of output.\n- Non-convergence: the two networks keep oscillating.\n- Vanishing gradient for G when D becomes too good.\n- Sensitive to hyperparameters; hard to evaluate.\nVariants: DCGAN (convolutional), conditional GAN (class label as an extra input), CycleGAN (image-to-image), StyleGAN (faces).\nApplications: image generation, synthetic data, super-resolution, image-to-image translation.",
      ask:["What is mode collapse?", "Applications of GANs"] }
  ];
  N["5.1.0"] = { q:"Explain image generation and DeepFake using GANs.", m:5,
      a:"Image generation with a GAN:\n1. Train the GAN on a set of real images (e.g. faces).\n2. After training, discard the discriminator.\n3. Feed random noise to the generator: each noise vector gives a new, realistic image that is not in the training set.\n4. Conditional GAN: give a label or text too, to control what is generated.\nDeepFake — synthetic media in which a person's face or voice is replaced with someone else's, so that they appear to say or do something they did not.\nHow it is made:\n- Autoencoder method: one shared encoder and two decoders (one per person). Encode a frame of A, decode it with B's decoder → B's face with A's expression.\n- GAN method: the generator creates the swapped face; the discriminator pushes it to look real.\nUses: film dubbing, education, entertainment.\nMisuse: misinformation, fraud, defamation, non-consensual content.\nDetection: unnatural blinking, lighting and edge artefacts; trained classifier networks; watermarking.",
      ask:["Ethical concerns of DeepFakes", "How can DeepFakes be detected?"] };
  N["5.2.0"] = { q:"Explain diffusion models for image generation. Compare them with GANs.", m:5,
      a:"<p><b>Diffusion model:</b> learns to generate images by reversing a gradual noising process.</p><ul><li><b>Forward process (fixed):</b> add a little Gaussian noise to an image at each of T steps, until it is pure noise. x0 → x1 → … → xT.</li><li><b>Reverse process (learned):</b> a neural network (U-Net) is trained to predict the noise added at each step, so that it can be removed. xT → … → x0.</li><li><b>Training loss:</b> ‖ε − ε<sub>θ</sub>(x<sub>t</sub>, t)‖²: the squared difference between the true noise and the predicted noise.</li><li><b>Generation:</b> start from random noise; denoise step by step; a text prompt can guide every step.</li></ul><p>Examples: Stable Diffusion (works in a compressed latent space), DALL·E, Midjourney.</p><table><tr><th></th><th>GAN</th><th>Diffusion model</th></tr><tr><td>Networks</td><td>Generator + discriminator</td><td>One denoising network</td></tr><tr><td>Training</td><td>Unstable (adversarial)</td><td>Stable</td></tr><tr><td>Diversity</td><td>Mode collapse possible</td><td>High</td></tr><tr><td>Generation speed</td><td>Fast: one pass</td><td>Slow: many steps</td></tr><tr><td>Image quality</td><td>High</td><td>Very high</td></tr></table>",
      ask:["Forward vs reverse diffusion process", "GAN vs diffusion model"] };
})();
